UPDATE tools SET long_description = E'Spendesk, c''est gestion des dépenses d''entreprise : cartes virtuelles, notes de frais, approbations. À partir de 99€/mois. Particulièrement pertinent pour les daf-finance et les manager-dsi.\n\nGain de temps estimé : 5h/mois pour un usage régulier.\n\nÀ garder si : équipe de 10+ avec dépenses fréquentes à contrôler. À éviter si : solo ou petite équipe — Qonto suffit. Rentable à partir de 10 collaborateurs avec budget variable.', long_description_en = E'Spendesk is corporate spend management: virtual cards, expense reports, approvals. Starting at €99/month. Most relevant for daf-finance and manager-dsi.\n\nEstimated time saving: 5h/month with regular use.\n\nKeep it if: team of 10+ with frequent expenses to control. Skip it if: solo ou petite équipe — Qonto suffit. Profitable starting from 10 employees with a variable budget.' WHERE slug = 'spendesk';
UPDATE tools SET long_description = E'ProtoPie, c''est prototypage interactif avancé sans code. Interactions complexes impossibles dans Figma. À partir de 11.26€/mois. Particulièrement pertinent pour les ux-ui.\n\nGain de temps estimé : 4h/mois pour un usage régulier.\n\nÀ garder si : micro-interactions complexes, prototypes haute fidélité avancés. À éviter si : figma suffit pour 90% des prototypes — doublon si usage basique. Pertinent uniquement pour des interactions que Figma ne peut pas faire.', long_description_en = E'ProtoPie is advanced interactive prototyping without code. Complex interactions impossible in Figma. Starting at €11.26/month. Most relevant for ux-ui.\n\nEstimated time saving: 4h/month with regular use.' WHERE slug = 'protopie';
