UPDATE tools SET long_description = E'Hotjar, c''est heatmaps, replays de sessions et sondages pour comprendre le comportement utilisateur. À partir de 27.71€/mois. Particulièrement pertinent pour les ux-ui et les product-manager.\n\nGain de temps estimé : 4h/mois pour un usage régulier.\n\nÀ garder si : site existant avec besoin de comprendre les parcours utilisateurs. À éviter si : postHog déjà en place — doublon replays. Free tier suffisant pour la plupart des projets. Si le budget le permet, posthog est souvent une meilleure option.', long_description_en = E'Hotjar is heatmaps, session replays, and surveys to understand user behaviour. Starting at €27.71/month. Most relevant for ux-ui and product-manager.\n\nEstimated time saving: 4h/month with regular use.\n\nIf budget allows, posthog is often a better fit.' WHERE slug = 'hotjar';
